#!/usr/bin/env python3
"""Oracle #1 reproducibility (docs/update-robustness-contract.md rev 1.2).

Runs tools/gen_update_fixtures.py twice into two fresh directories and requires
  * both runs byte-identical, file set identical;
  * every file's sha256 == testdata/s101/fixtures.toml [[update_fixture]] entry;
  * the committed bytes under testdata/s101/updates/ == the regenerated bytes.
Exit 0 on pass, 1 on any mismatch. Never skips.
"""
import hashlib
import os
import subprocess
import sys
import tempfile


def tree(root):
    out = {}
    for d, _, files in os.walk(root):
        for f in files:
            p = os.path.join(d, f)
            rel = os.path.relpath(p, root).replace(os.sep, "/")
            with open(p, "rb") as fh:
                out[rel] = fh.read()
    return out


def manifest(path):
    m = {}
    cur = None
    in_fixture = False
    with open(path, "rb") as fh:
        for raw in fh.read().decode("utf-8").splitlines():
            line = raw.strip()
            if line.startswith("["):
                in_fixture = line in ("[[update_fixture]]", "[[cancel_fixture]]")
                cur = None
                continue
            if not in_fixture:
                continue
            if line.startswith("path = "):
                cur = line.split('"')[1]
            elif line.startswith("sha256 = ") and cur:
                m[cur] = line.split('"')[1]
    return m


def main():
    if len(sys.argv) != 3:
        print("usage: check_update_fixtures.py <repo> <scratch-dir>")
        return 1
    repo, scratch = sys.argv[1], sys.argv[2]
    gen = os.path.join(repo, "tools", "gen_update_fixtures.py")
    os.makedirs(scratch, exist_ok=True)
    runs = []
    for i in (1, 2):
        out = tempfile.mkdtemp(prefix="run%d_" % i, dir=scratch)
        subprocess.run([sys.executable, gen, "--out", out], check=True, stdout=subprocess.DEVNULL)
        runs.append(tree(out))
    fail = 0
    if runs[0] != runs[1]:
        print("FAIL generator output differs between two runs")
        for rel in sorted(set(runs[0]) | set(runs[1])):
            if runs[0].get(rel) != runs[1].get(rel):
                print("  differs: " + rel)
        fail = 1
    want = manifest(os.path.join(repo, "testdata", "s101", "fixtures.toml"))
    gen_rel = {"updates/" + k: v for k, v in runs[0].items()}
    if set(want) != set(gen_rel):
        print("FAIL fixtures.toml set != generated set")
        print("  only in toml: %s" % sorted(set(want) - set(gen_rel)))
        print("  only generated: %s" % sorted(set(gen_rel) - set(want)))
        fail = 1
    committed_root = os.path.join(repo, "testdata", "s101")
    for rel in sorted(gen_rel):
        h = hashlib.sha256(gen_rel[rel]).hexdigest()
        ok = want.get(rel) == h
        cpath = os.path.join(committed_root, *rel.split("/"))
        committed = open(cpath, "rb").read() if os.path.exists(cpath) else None
        same = committed == gen_rel[rel]
        print("%s %s %s%s" % ("ok  " if ok and same else "FAIL", h, rel,
                              "" if same else ("  (committed missing)" if committed is None
                                               else "  (committed bytes differ)")))
        if not (ok and same):
            fail = 1
    print("update fixtures reproducible: %s (%d files, 2 runs)" % ("FAIL" if fail else "ok", len(gen_rel)))
    return fail


if __name__ == "__main__":
    sys.exit(main())
